import java.util.Scanner;

public class Main {
    static final int MAX = 1000007;
    static final int mod = 1000000007;
    static boolean[] odw = new boolean[MAX];
    static long[] ile = new long[MAX];
    static long[] cc = new long[MAX];
    static long[] dp = new long[MAX];

    public static int r(Scanner sc) {
        return sc.nextInt();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long wyn = 1;
        int p = r(sc);
        int k = r(sc);

        for (int i = 0; i < p; i++) {
            if (!odw[i]) {
                int dl = 0;
                long akt = i;
                while (!odw[(int) akt]) {
                    odw[(int) akt] = true;
                    akt = (k * akt) % p;
                    dl++;
                }
                cc[dl]++;
            }
        }

        for (int i = 1; i <= p; i++) {
            dp[i] = (cc[i] * i) % mod;
        }

        for (int i = 1; i <= p; i++) {
            ile[i] = (ile[i] + dp[i]) % mod;
            for (int j = i + i; j <= p; j += i) {
                ile[j] = (dp[i] + ile[j]) % mod;
            }
        }

        for (int i = 1; i <= p; i++) {
            if (i == 1) {
                for (int j = 0; j < cc[i] - 1; j++) {
                    wyn = (wyn * cc[i]) % mod;
                }
            } else {
                for (int j = 0; j < cc[i]; j++) {
                    wyn = (wyn * ile[i]) % mod;
                }
            }
        }

        if (k == 1) {
            wyn = (wyn * ile[1]) % mod;
        }

        System.out.println((int) wyn);
        sc.close();
    }
}
